package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_ValidWithLeadingSpaces() {
        byte[] buffer = "   0755 ".getBytes();
        assertEquals(493L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_ValidWithTrailingNul() {
        byte[] buffer = "000123\0".getBytes();
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_ValidWithDoubleTrailingNulOrSpace() {
        // Testing the "May have additional NUL or space" block
        byte[] buffer = "077\0\0".getBytes();
        assertEquals(63L, TarUtils.parseOctal(buffer, 0, buffer.length));

        byte[] buffer2 = "077  ".getBytes();
        assertEquals(63L, TarUtils.parseOctal(buffer2, 0, buffer2.length));
    }

    @Test
    public void testParseOctal_AllNUL() {
        byte[] buffer = new byte[]{0, 0, 0, 0};
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 4));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooSmall() {
        byte[] buffer = "0".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidTrailer() {
        // Last byte is 'A', not space or NUL
        byte[] buffer = "077A".getBytes();
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigitLow() {
        // ' ' is less than '0'
        byte[] buffer = "0-5 ".getBytes();
        // '-' is 45, '0' is 48.
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigitHigh() {
        // '8' is valid in decimal but the code checks currentByte >= '7' 
        // Wait, looking at the code: if (currentByte < '0' || currentByte >= '7')
        // This means the code only accepts '0', '1', '2', '3', '4', '5', '6'.
        // '7' will trigger the exception.
        byte[] buffer = "07 ".getBytes();
        TarUtils.parseOctal(buffer, 0, 3);
    }

    @Test
    public void testParseOctal_WithOffset() {
        byte[] buffer = "junk 0123  ".getBytes();
        // offset 5, length 7 -> "0123  "
        assertEquals(67L, TarUtils.parseOctal(buffer, 5, 7));
    }

    @Test
    public void testParseOctal_MaxAllowedDigit() {
        // Checking the boundary of the if condition: currentByte >= '7' 
        // So '6' should be the highest valid digit.
        byte[] buffer = "666 ".getBytes();
        assertEquals(446L, TarUtils.parseOctal(buffer, 0, 4));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidCharInMiddle() {
        // 'X' is not a digit
        byte[] buffer = "0X0 ".getBytes();
        TarUtils.parseOctal(buffer, 0, 4);
    }
}
